import React, { useState } from 'react';
import { Card, Select, Input, DatePicker, Button, Space } from 'antd';
import dayjs from 'dayjs';
import HybridPathInput from './HybridPathInput';
import { airports } from './data/airports';
import './styles/NormalRouteBuilder.css';

const { RangePicker } = DatePicker;

const NormalRouteBuilder = ({ onSearch }) => {
  const [path, setPath] = useState('');
  const [sourcesExcluded, setSourcesExcluded] = useState([]);
  const [apiKey, setApiKey] = useState('');
  const [dateRange, setDateRange] = useState(null);

  // Convert airports data to options format for Sources Excluded
  const airportOptions = airports.map(airport => ({
    value: airport.IATA,
    label: `${airport.IATA} - ${airport.Name} (${airport.Country})`
  }));

  const handleSearch = () => {
    if (!path) {
      return;
    }

    onSearch?.({
      path,
      sourcesExcluded,
      apiKey,
      dateRange: dateRange ? [dateRange[0].format('YYYY-MM-DD'), dateRange[1].format('YYYY-MM-DD')] : null
    });
  };

  return (
    <Card title="Normal Route Builder" className="normal-route-builder">
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
        {/* Path Input */}
        <div>
          <div className="element-label">Path:</div>
          <HybridPathInput
            value={path}
            onChange={setPath}
            placeholder="Enter path (e.g. NRT/HND-OAK/SFO-JFK/EWR)"
          />
        </div>

        {/* Sources Excluded */}
        <div>
          <div className="element-label">Sources Excluded:</div>
          <Select
            mode="multiple"
            style={{ width: '100%' }}
            placeholder="Select airports to exclude"
            value={sourcesExcluded}
            onChange={setSourcesExcluded}
            options={airportOptions}
            allowClear
            showSearch
            filterOption={(input, option) => {
              const searchLower = input.toLowerCase();
              return option.value.toLowerCase().includes(searchLower) || 
                     option.label.toLowerCase().includes(searchLower);
            }}
          />
        </div>

        {/* API Key */}
        <div>
          <div className="element-label">API Key:</div>
          <Input.Password
            value={apiKey}
            onChange={(e) => setApiKey(e.target.value)}
            placeholder="Enter your API key"
            style={{ width: '100%' }}
          />
        </div>

        {/* Date Range */}
        <div>
          <div className="element-label">Date Range:</div>
          <RangePicker
            value={dateRange}
            onChange={setDateRange}
            style={{ width: '100%' }}
            format="YYYY-MM-DD"
          />
        </div>

        {/* Search Button */}
        <Button
          type="primary"
          onClick={handleSearch}
          disabled={!path}
          style={{ width: '100%' }}
        >
          Search
        </Button>
      </Space>
    </Card>
  );
};

export default NormalRouteBuilder;
